const CREAM = '#fff6ef';
const SUNSET = { gradient: 'linear', from: [0.33, 0], to: [0.67, 1],
  stops: [{ light: '#ff9a5c', dark: '#b8562e' }, { light: '#ff6b4a', dark: '#9c3826' }] };
const INFINITY = 'M12 12c-2-2.7-3.7-4-5.5-4a4 4 0 0 0 0 8c1.8 0 3.5-1.3 5.5-4zm0 0c2 2.7 3.7 4 5.5 4a4 4 0 0 0 0-8c-1.8 '
  + '0-3.5 1.3-5.5 4z';

function grouped(n) {
  return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}

function render(ctx) {
  // Sizes are in the prototype's units: a widget is 170 of them tall. Bricolage's line is 1.2 times its size, so
  // the gaps around the count are 0.1 of its size shorter than the prototype's.
  const u = ctx.height / 170;
  const first = ctx.data.first;
  const days = first && first.since
    ? Math.max(0, Math.round((new Date(ctx.today.date) - new Date(first.since)) / 86400000)) : null;
  const line = (value) => ({ type: 'text', value, size: 12.5 * u, weight: 'semibold', color: CREAM, opacity: 0.8,
    lineLimit: 1, minScale: 0.8 });

  return {
    type: 'zstack', align: 'topLeading',
    frame: { maxWidth: 'infinity', maxHeight: 'infinity' },
    widgetBackground: SUNSET,
    children: [
      { type: 'button', action: 'set', rowId: first ? first.id : null,
        label: days === null ? 'Together, set the day of your first date'
          : 'Together, ' + grouped(days) + (days === 1 ? ' day' : ' days') + ' since our first date',
        children: [
        { type: 'vstack', align: 'leading', spacing: 0,
          padding: { top: 13.5 * u, leading: 16 * u, trailing: 16 * u },
          frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topLeading' },
          children: [
            { type: 'hstack', spacing: 5 * u, frame: { height: 16 * u }, children: [
              { type: 'path', d: INFINITY, viewBox: [0, 0, 24, 24], frame: { width: 15 * u, height: 15 * u },
                stroke: { color: CREAM, width: 2.6 * 15 * u / 24, cap: 'round' } },
              { type: 'text', value: 'Together', size: 13 * u, weight: 'bold', color: CREAM, lineLimit: 1 } ] },
            { type: 'text', value: days === null ? 'Day one' : grouped(days), fontName: 'Bricolage Grotesque Display',
              size: 40 * u, kerning: -1.2 * u, color: CREAM, accent: true, lineLimit: 1, minScale: 0.5,
              padding: { top: 4 * u } },
            { type: 'vstack', align: 'leading', spacing: 0, padding: { top: 1 * u },
              children: days === null ? [line('tap to set the day'), line('of your first date')]
                : [line(days === 1 ? 'day since' : 'days since'), line('our first date')] },
          ] } ] },
    ],
  };
}
